import { Router } from 'express';
import { sql } from 'drizzle-orm';
import { parsePagination, paginationOffset } from '../utils/pagination';
import { db } from '../db';
import { User } from '../models/user';

const router = Router();

router.get('/api/users', async (req, res) => {
  const { page, perPage } = parsePagination(req.query);
  const offset = paginationOffset({ page, perPage });

  const [users, countResult] = await Promise.all([
    db.select().from(User).limit(perPage).offset(offset),
    db.select({ count: sql<number>`cast(count(*) as integer)` }).from(User),
  ]);

  const total = Number(countResult[0].count);
  res.json({
    data: users,
    pagination: {
      page,
      per_page: perPage,
      total,
      total_pages: Math.ceil(total / perPage),
    },
  });
});

router.get('/api/users/:id', async (req, res) => {
  const user = await db.select().from(User).where({ id: req.params.id }).first();
  if (!user) return res.status(404).json({ error: 'Not found' });
  res.json({ user });
});

export default router;

